var wm=UnityEngine.Object.FindObjectOfType<WaveManager>();var gm=UnityEngine.Object.FindObjectOfType<GameManager>();gm.StartGame();Time.timeScale=8;return new{frame=Time.frameCount,state=gm.CurrentState.ToString(),towers=UnityEngine.Object.FindObjectsOfType<Tower>().Select(t=>new{t.name,items=t.Backpack.Items.Count,range=t.CurrentRange,visual=t.transform.Find("Visual")!=null}).ToArray(),units=UnityEngine.Object.FindObjectsOfType<Unit>().Select(u=>u.transform.position.ToString()).ToArray()};
